const fs = require('fs')
const path = require('path')
const os = require('os')
const { scan } = require('@dotenvx/primitives')

function filepath (env) {
  const home = os.homedir()
  const directory = env.DOTENVX_CONFIG || (process.platform === 'darwin'
    ? path.join(home, 'Library', 'Preferences', 'dotenvx')
    : process.platform === 'win32'
      ? path.join(env.APPDATA || path.join(home, 'AppData', 'Roaming'), 'dotenvx', 'Config')
      : path.join(env.XDG_CONFIG_HOME || path.join(home, '.config'), 'dotenvx'))
  return path.resolve(directory, '.env')
}

function value (source, key) {
  const values = scan(source).parsed[key]
  return values && values[values.length - 1]
}

function failure (error) {
  if (error.code === 'ENOENT') return undefined
  const safe = new Error('could not read dotenvx settings')
  safe.code = 'SETTINGS_FAILED'
  throw safe
}

module.exports = {
  async get (key, env) {
    try { return value(await fs.promises.readFile(filepath(env), 'utf8'), key) } catch (error) { return failure(error) }
  },
  getSync (key, env) {
    try { return value(fs.readFileSync(filepath(env), 'utf8'), key) } catch (error) { return failure(error) }
  }
}
